const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'₱'+Number(n||0).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});
// New installations start with completely empty records. Totals and reports calculate from entries you add.
const emptyData={orders:[],stock:[],products:[],expenses:[],requests:[],shiftChecks:[],auditLog:[]};
if(localStorage.bbDataVersion!=='2'){localStorage.removeItem('bbData');localStorage.bbDataVersion='2'}
function load(){try{return {...emptyData,...(JSON.parse(localStorage.bbData)||{})}}catch(e){return {...emptyData}}}
let db=load(), cart=JSON.parse(sessionStorage.getItem('bbCart')||'[]'), activeShiftType='Opening';
// Daily views roll over using the shop's local calendar date; stored records are never cleared.
function localDateKey(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`}
function todaysOrders(){const today=localDateKey();return db.orders.filter(o=>recordDayKey(o)===today)}
function todaysExpenses(){const today=localDateKey();return db.expenses.filter(e=>e.date===today)}
function todaysShifts(){const today=localDateKey();return (db.shiftChecks||[]).filter(c=>c.dayKey===today)}
function recordDayKey(record){if(record?.dayKey)return record.dayKey;const raw=record?.date||record?.createdAt||'';if(/^\d{4}-\d{2}-\d{2}/.test(String(raw)))return String(raw).slice(0,10);const parsed=new Date(raw);return Number.isNaN(parsed.getTime())?'':localDateKey(parsed)}
function todaysRecords(records){const today=localDateKey();return (records||[]).filter(r=>recordDayKey(r)===today)}
function persistCart(){sessionStorage.setItem('bbCart',JSON.stringify(cart))}
function savePosDraft(){let d={customer:$('#customer')?.value||'',cash:$('#cash')?.value||'',custom:$('#custom')?.value||''};sessionStorage.setItem('bbPosDraft',JSON.stringify(d))}
function restorePosDraft(){try{let d=JSON.parse(sessionStorage.getItem('bbPosDraft')||'{}');if($('#customer'))$('#customer').value=d.customer||'';if($('#cash'))$('#cash').value=d.cash||'';if($('#custom'))$('#custom').value=d.custom||'';['customer','cash','custom'].forEach(id=>$('#'+id)?.addEventListener('input',savePosDraft))}catch(e){}}
function recipeForProduct(p){
 const n=p.name.toLowerCase(), coffee=p.category==='Coffee', refresher=p.category==='Refreshers';
 const r=[]; const add=(name,qty)=>r.push({name,qty});
 if(coffee) add('Espresso coffee beans',18);
 if(refresher){ add('Soda water',180); add('Ice',120); }
 else { add('Fresh milk',coffee?(n.includes('americano')?0:180):200); add('Ice',120); }
 if(n.includes('caramel')) add(n.includes('salted')?'Salted caramel syrup':'Caramel syrup',25);
 if(n.includes('vanilla')) add('Vanilla syrup',20);
 if(n.includes('hazelnut')) add('Hazelnut syrup',20);
 if(n.includes('mocha')||n.includes('chocolate')||n.includes('cocoa')) add(n.includes('cocoa')?'Cocoa powder':'Mocha/chocolate sauce',25);
 if(n.includes('matcha')) add('Matcha powder',8);
 if(n.includes('blueberry')) add('Blueberry syrup',25);
 if(n.includes('strawberry')) add('Strawberry syrup',25);
 if(n.includes('green apple')) add('Green apple syrup',25);
 if(n.includes('lychee')) add('Lychee syrup',25);
 if(n.includes('oreo')) add('Oreo cookies/crumbs',15);
 if(n.includes('spanish')||n.includes('tres leches')) { add('Condensed milk',25); add('Evaporated milk',25); }
 if(n.includes('dirty matcha')) add('Matcha powder',8);
 if(refresher && !r.some(x=>x.name.includes('syrup'))) add('Sugar syrup',20);
 add('Cups',1); add('Cup lids',1); add('Straws',1);
 return r.filter(x=>x.qty>0);
}
function ensureRecipes(){let changed=false;db.products.forEach(p=>{if(!Array.isArray(p.recipe)||!p.recipe.length){p.recipe=recipeForProduct(p);p.recipeSuggested=true;changed=true}});if(changed)save()}
function productStockCheck(p,qty=1){const recipe=p.recipe||recipeForProduct(p);const shortages=recipe.filter(r=>{const item=db.stock.find(s=>s.name.toLowerCase()===r.name.toLowerCase());return !item||Number(item.qty)<r.qty*qty});return {available:shortages.length===0,shortages}}
function applyOrderStock(order,direction){if(!order||(direction>0&&order.stockDeducted)||(direction<0&&!order.stockDeducted))return;for(const line of (order.lines||[])){const recipe=line.recipe||db.products.find(p=>p.name===line.name)?.recipe||recipeForProduct(line);for(const r of recipe){const stock=db.stock.find(s=>s.name.toLowerCase()===r.name.toLowerCase());if(stock){const amount=Number(r.qty||0)*Number(line.qty||1);stock.qty=Math.max(0,Number(stock.qty||0)-(direction*amount))}}}order.stockDeducted=direction>0;save()}
function expectedCashInDrawer(){return todaysOrders().filter(o=>!['Cancelled','Voided','Refunded'].includes(o.status)).reduce((sum,o)=>sum+Number(o.total||0),0)}
function seedStarterMenu(){
// Starter drinks are taken from the Project Charter's Company Products menu.
// Example prices/costs are placeholders; replace them with the shop's approved values.
const drinks=[
['Americano','Coffee',95,35],['Cafe Latte','Coffee',110,45],['Caramel Latte','Coffee',120,50],['Caramel Macchiato','Coffee',130,60],['Caramelized Mocha Latte','Coffee',135,62],['Dirty Matcha','Coffee',140,65],['Hazelnut Latte','Coffee',125,55],['Salted Caramel Latte','Coffee',130,58],['Spanish Latte','Coffee',120,55],['Tres Leches Latte','Coffee',140,65],['Vanilla Latte','Coffee',120,52],
['Blueberry Milk','Non-Coffee',110,48],['Caramel Milk','Non-Coffee',110,48],['Chocolate Milk','Non-Coffee',110,50],['Strawberry Milk','Non-Coffee',110,48],['Oreo Milk','Non-Coffee',120,55],['Matcha Milk','Non-Coffee',125,58],['Strawberry Matcha','Non-Coffee',135,62],['Strawberry Cocoa','Non-Coffee',120,54],['Milky Berry Oreo','Non-Coffee',130,60],
['Blueberry Fizz','Refreshers',105,42],['Green Apple Fizz','Refreshers',105,42],['Lychee Fizz','Refreshers',105,42],['Strawberry Fizz','Refreshers',105,42]
];
let changed=false;drinks.forEach(([name,category,price,cost])=>{if(!db.products.some(p=>p.name.toLowerCase()===name.toLowerCase())){db.products.push({name,category,price,cost,image:'',sample:true});changed=true}});
// The charter names the drink categories but does not prescribe ingredient quantities.
// These are suggested inventory records for setup; enter actual counts from the shop.
const ingredients=[
['Espresso coffee beans',0,'g',500],['Fresh milk',0,'ml',2000],['Condensed milk',0,'ml',1000],['Evaporated milk',0,'ml',1000],['Whipping cream',0,'ml',500],['Matcha powder',0,'g',100],['Chocolate powder',0,'g',250],['Cocoa powder',0,'g',250],['Caramel syrup',0,'ml',500],['Vanilla syrup',0,'ml',500],['Hazelnut syrup',0,'ml',500],['Salted caramel syrup',0,'ml',500],['Mocha/chocolate sauce',0,'ml',500],['Blueberry syrup',0,'ml',500],['Strawberry syrup',0,'ml',500],['Green apple syrup',0,'ml',500],['Lychee syrup',0,'ml',500],['Oreo cookies/crumbs',0,'g',250],['Sugar syrup',0,'ml',1000],['Soda water',0,'ml',2000],['Ice',0,'g',2000],['Cups',0,'pcs',50],['Cup lids',0,'pcs',50],['Straws',0,'pcs',50]
];
ingredients.forEach(([name,qty,unit,min])=>{if(!db.stock.some(x=>x.name.toLowerCase()===name.toLowerCase())){db.stock.push({name,qty,unit,min,suggested:true});changed=true}});
// One-time demo opening stock so the POS can be tested immediately. These are editable estimates, not verified shop counts.
if(localStorage.bbOpeningStockSeeded!=='v1'){
 const openingStock={
  'Espresso coffee beans':2000,'Fresh milk':10000,'Condensed milk':3000,'Evaporated milk':3000,'Whipping cream':2000,
  'Matcha powder':500,'Chocolate powder':1000,'Cocoa powder':500,'Caramel syrup':1500,'Vanilla syrup':1500,
  'Hazelnut syrup':1000,'Salted caramel syrup':1000,'Mocha/chocolate sauce':1500,'Blueberry syrup':1000,
  'Strawberry syrup':1000,'Green apple syrup':1000,'Lychee syrup':1000,'Oreo cookies/crumbs':1000,
  'Sugar syrup':3000,'Soda water':6000,'Ice':10000,'Cups':200,'Cup lids':200,'Straws':200
 };
 db.stock.forEach(item=>{const amount=openingStock[item.name];if(amount!==undefined&&Number(item.qty||0)===0&&item.suggested!==false){item.qty=amount;item.suggested=true}});
 localStorage.bbOpeningStockSeeded='v1';changed=true;
}
if(changed){localStorage.bbMenuSeeded='charter-menu-v1';save()}
ensureRecipes();
}

