const INITIAL_OWNER={id:'bb-owner-001',name:'Franchesca Jannel Camacho',username:'chesca@gmail.com',password:'jannel123',role:'owner'};
function getUsers(){try{return JSON.parse(localStorage.bbUsers)||[]}catch(e){return []}}
function ensureInitialOwner(){let users=getUsers();if(!users.some(u=>u.username.toLowerCase()===INITIAL_OWNER.username.toLowerCase())){users.unshift({...INITIAL_OWNER});saveUsers(users)}}
function saveUsers(users){localStorage.bbUsers=JSON.stringify(users)}
function currentUser(){try{return JSON.parse(localStorage.bbCurrentUser)||null}catch(e){return null}}
function setCurrentUser(user){localStorage.bbCurrentUser=JSON.stringify(user)}
function logout(){localStorage.removeItem('bbCurrentUser');location.href='../index.html'}
function status(s){let c=['Completed','Approved','Verified','Available'].includes(s)?'green':['Cancelled','Rejected','Out-of-Stock'].includes(s)?'red':['Pending','For approval','Low-Stock','Preparing'].includes(s)?'gold':'';return `<span class="pill ${c}">${s}</span>`}
function modal(title,body,submit='Save',cb=null){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;$('#modal-submit').textContent=submit;$('#modal-submit').onclick=()=>{let result=cb?cb():true;if(result!==false)closeModal()};$('#modal').classList.add('show')}
function closeModal(){$('#modal').classList.remove('show')}
function toast(msg){let el=document.createElement('div');el.className='notice success';el.textContent=msg;document.querySelector('.main')?.prepend(el);setTimeout(()=>el.remove(),2500)}
function pageHead(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><div class="sub">${sub}</div></div><div class="actions">${actions}</div></div>`}
function stats(items){return `<div class="grid stats">${items.map(x=>`<div class="stat"><div class="label">${x[0]}</div><strong>${x[1]}</strong><small>${x[2]||''}</small></div>`).join('')}</div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">No records yet</td></tr>`}</tbody></table></div>`}
function ownerNav(){return [['dashboard','Dashboard','⌂'],['pos','Orders / POS','▣'],['history','Order history','◷'],['inventory','Inventory','▤'],['costing','Menu & costing','◈'],['reports','Reports & expenses','▥'],['approvals','Approvals & verification','✓'],['shift','Shift overview','◷'],['settings','Settings & backup','⚙']]}
function baristaNav(){return [['dashboard','Dashboard','⌂'],['pos','Orders / POS','▣'],['stock','Stock status','▤'],['shift','Shift check','◷']]}
function shell(role,active,content){let nav=role==='owner'?ownerNav():baristaNav(), user=currentUser();document.body.innerHTML=`<header class="topbar"><div class="brand"><img src="../assets/logo.png"><span>BREWS & BLESSINGS</span></div><div class="top-right"><span>${user?escapeHTML(user.name):'Staff'} · ${role==='owner'?'Owner / Manager':'Barista'}</span><a href="#" onclick="logout();return false">Log out</a></div></header><div class="layout"><aside class="sidebar"><div class="side-label">Workspace</div><nav class="nav">${nav.map(n=>`<a class="${active===n[0]?'active':''}" href="${n[0]}.html"><span class="ico">${n[2]}</span>${n[1]}</a>`).join('')}</nav><div class="side-foot">Secure staff access<br>Session ends after inactivity.</div></aside><main class="main">${content}</main></div><div class="modal-backdrop" id="modal"><div class="modal"><div class="modal-head"><h2 id="modal-title">Modal</h2><button class="close" onclick="closeModal()">×</button></div><div id="modal-body"></div><div class="modal-actions"><button class="btn" onclick="closeModal()">Cancel</button><button class="btn primary" id="modal-submit">Save</button></div></div></div>`}
function ownerDashboard(){let total=todaysOrders().filter(o=>o.status==='Completed').reduce((a,o)=>a+o.total,0);return pageHead('Dashboard','A live overview of today’s store activity')+stats([["Today's sales",money(total),"Cash transactions"],['Orders',todaysOrders().length,'Orders recorded today'],['Available stock',db.stock.filter(s=>s.qty>s.min).length,'Ingredient items'],['Low / out of stock',db.stock.filter(s=>s.qty<=s.min).length,'Needs attention']])+`<div class="grid two"><section class="panel"><h2>Recent orders</h2>${table(['Order #','Customer','Items','Total','Status'],todaysOrders().slice(0,5).map(o=>`<tr><td>#${o.id}</td><td>${o.customer}</td><td>${o.items}</td><td>${money(o.total)}</td><td>${status(o.status)}</td></tr>`).join(''))}<div class="spacer"></div><a class="btn small" href="pos.html">Open POS</a></section><section class="panel"><h2>Low-stock alerts</h2>${db.stock.filter(s=>s.qty<=s.min).map(s=>`<div class="cartline"><span>${s.name}<br><small class="muted">${s.qty} ${s.unit} remaining</small></span>${status(s.qty===0?'Out-of-Stock':'Low-Stock')}</div>`).join('')||'<div class="empty">All stock levels are healthy.</div>'}</section></div><section class="panel"><h2>Sales overview</h2><div class="chart">${[40,58,45,75,55,90,68].map((v,i)=>`<div class="bar" style="height:${v}%"><span>${['M','T','W','T','F','S','S'][i]}</span></div>`).join('')}</div></section>`}
function orderHistoryPage(){
 const params=new URLSearchParams(location.search);
 const selectedDate=params.get('date')||localDateKey();
 const selectedOrders=db.orders.filter(o=>recordDayKey(o)===selectedDate).sort((a,b)=>String(b.time||'').localeCompare(String(a.time||'')));
 const completed=selectedOrders.filter(o=>o.status==='Completed');
 const sales=completed.reduce((sum,o)=>sum+Number(o.total||0),0);
 const rows=selectedOrders.map(o=>`<tr><td>#${escapeHTML(o.id)}</td><td>${escapeHTML(o.date||'')}</td><td>${escapeHTML(o.time||'')}</td><td>${escapeHTML(o.customer||'Walk-in')}</td><td>${escapeHTML(o.items||'')}</td><td>${money(o.total)}</td><td>${status(o.status)}</td></tr>`).join('');
 return pageHead('Order history','Owner-only archive. Choose any date to review its transactions.')+
 stats([['All-time orders',db.orders.length,'Historical records'],['Orders on selected date',selectedOrders.length,selectedDate],['Completed sales',money(sales),'Selected date only']])+ 
 `<section class="panel"><div class="inline" style="justify-content:space-between;flex-wrap:wrap"><div><h2>Browse order history</h2><p class="muted">Select a date to view orders recorded on that day.</p></div><div class="field" style="min-width:220px"><label for="history-date">Choose date</label><input type="date" id="history-date" value="${escapeHTML(selectedDate)}" max="${localDateKey()}" onchange="filterOrderHistory(this.value)"></div></div><div class="inline" style="justify-content:flex-end"><button class="btn small" onclick="filterOrderHistory(localDateKey())">Today</button></div>${table(['Order #','Date','Time','Customer','Items','Total','Status'],rows)}</section>`
}
function filterOrderHistory(date){if(!date)return;location.href='history.html?date='+encodeURIComponent(date)}
function baristaDashboard(){return pageHead('Dashboard · Morning shift','Welcome back. Here is your shift at a glance.')+stats([['Orders today',todaysOrders().length,'Recorded orders'],['Pending',todaysOrders().filter(o=>o.status==='Pending').length,'Waiting to prepare'],['Preparing',todaysOrders().filter(o=>o.status==='Preparing').length,'In progress'],['Low-stock alerts',db.stock.filter(s=>s.qty<=s.min).length,'Please inform the owner']])+`<div class="grid two"><section class="panel"><h2>Current orders</h2>${table(['Order #','Items','Time','Status','Action'],todaysOrders().map(o=>`<tr><td>#${o.id}</td><td>${o.items}</td><td>${o.time}</td><td>${status(o.status)}</td><td><button class="btn small" onclick="updateOrder('${o.id}')">Update</button></td></tr>`).join(''))}</section><section class="panel"><h2>Stock status</h2>${db.stock.filter(s=>s.qty<=s.min).map(s=>`<div class="cartline"><span>${s.name}</span>${status(s.qty===0?'Out-of-Stock':'Low-Stock')}</div>`).join('')||'<div class="empty">No low-stock alerts.</div>'}<div class="notice">Inventory is read-only for Barista accounts. Please notify the Owner/Manager for restocking.</div><a class="btn small" href="stock.html">View stock status</a></section></div>`}
function quickOrderStatusPanel(){let rows=todaysOrders().map(o=>`<tr><td><b>#${escapeHTML(o.id)}</b><br><small class="muted">${escapeHTML(o.customer||'Walk-in')}</small></td><td>${escapeHTML(o.items)}</td><td>${money(o.total)}</td><td>${status(o.status)}</td><td><div class="inline"><select id="quick-status-${escapeHTML(o.id)}" aria-label="New status for order ${escapeHTML(o.id)}"><option ${o.status==='Pending'?'selected':''}>Pending</option><option ${o.status==='Preparing'?'selected':''}>Preparing</option><option ${o.status==='Completed'?'selected':''}>Completed</option></select><button class="btn small primary" onclick="saveQuickOrderStatus('${String(o.id).replace(/'/g,"\\'")}')">Save</button></div></td></tr>`).join('');return `<section class="panel quick-orders-panel"><div class="inline" style="justify-content:space-between"><h2>Quick order status</h2><span class="muted">Edit without scrolling to the bottom</span></div>${rows?table(['Order / Customer','Items','Total','Current status','Change status'],rows):'<div class="empty">No orders recorded today yet.</div>'}</section>`}
function saveQuickOrderStatus(id){let order=db.orders.find(o=>String(o.id)===String(id));let select=$('#quick-status-'+CSS.escape(String(id)));if(!order||!select)return toast('Order could not be found.');order.status=select.value;save();location.reload()}
function posPage(role){return pageHead('Orders / POS',"Today's orders start fresh each day; all previous transactions remain in history")+stats([['Orders today',todaysOrders().length,''],['Pending',todaysOrders().filter(o=>o.status==='Pending').length,''],['Preparing',todaysOrders().filter(o=>o.status==='Preparing').length,''],['Completed',todaysOrders().filter(o=>o.status==='Completed').length,'']])+quickOrderStatusPanel()+`<div class="grid two pos-layout"><section class="panel"><h2>Choose a drink</h2><div class="product-grid">${db.products.map((p,i)=>{let check=productStockCheck(p);return `<button class="product" ${check.available?`onclick="addCart(${i})"`:'disabled title="Unavailable: ingredient stock is insufficient"'} style="${check.available?'':'opacity:.48;cursor:not-allowed'}">${p.image?`<img class="product-photo" src="${p.image}" alt="${escapeHTML(p.name)}">`:`<div class="product-photo product-placeholder">☕</div>`}<b>${escapeHTML(p.name)}</b><span>${escapeHTML(p.category)}</span><strong>${money(p.price)}</strong>${check.available?'':'<small class="pill red">Unavailable - Out of stock</small>'}</button>`}).join('')}</div></section><section class="panel pos-order-panel"><h2>Current order</h2><div class="field"><label>Customer name (optional)</label><input id="customer" placeholder="Walk-in customer"></div><div class="field"><label>Order notes / customization</label><textarea id="custom" rows="2" placeholder="e.g. less ice, oat milk, no sugar"></textarea></div><div id="cart-items">${cartHTML()}</div><div class="total"><span>Total</span><span id="cart-total">${money(cart.reduce((a,c)=>a+c.price*c.qty,0))}</span></div><div class="field"><label>Cash received</label><input type="number" id="cash" min="0" placeholder="0.00"></div><div class="notice">Cash payments only. Online payment processing is outside the project scope.</div><button class="btn primary" style="width:100%" onclick="checkout()">Confirm cash payment</button></section></div><section class="panel"><h2>Current orders</h2>${table(['Order #','Customer','Items','Total','Status','Action'],todaysOrders().map(o=>`<tr><td>#${o.id}</td><td>${escapeHTML(o.customer)}</td><td>${escapeHTML(o.items)}</td><td>${money(o.total)}</td><td>${status(o.status)}</td><td><button class="btn small" onclick="updateOrder('${o.id}')">Update</button> <button class="btn small" onclick="cancelOrder('${o.id}')">Cancel</button> ${role==='barista'?`<button class="btn small" onclick="refundRequest('${o.id}')">Refund request</button>`:''}</td></tr>`).join(''))}</section>`}
function cartHTML(){return cart.length?cart.map((c,i)=>`<div class="cartline"><span>${c.name}<br><small class="muted">${money(c.price)} each</small></span><span class="qty"><button onclick="changeQty(${i},-1)">−</button>${c.qty}<button onclick="changeQty(${i},1)">+</button><b>${money(c.qty*c.price)}</b></span></div>`).join(''):'<div class="empty">Select drinks to add them to the order.</div>'}
function addCart(i){let p=db.products[i];if(!p)return;let item=cart.find(c=>c.name===p.name),nextQty=(item?.qty||0)+1,check=productStockCheck(p,nextQty);if(!check.available)return toast(`${p.name} is unavailable because one or more ingredients are out of stock.`);item?item.qty++:cart.push({...p,recipe:p.recipe||recipeForProduct(p),qty:1});persistCart();$('#cart-items').innerHTML=cartHTML();$('#cart-total').textContent=money(cart.reduce((a,c)=>a+c.price*c.qty,0))}
function changeQty(i,n){cart[i].qty+=n;if(cart[i].qty<=0)cart.splice(i,1);persistCart();$('#cart-items').innerHTML=cartHTML();$('#cart-total').textContent=money(cart.reduce((a,c)=>a+c.price*c.qty,0))}
function checkout(){if(!cart.length)return toast('Add at least one drink first.');for(const line of cart){let check=productStockCheck(line,line.qty);if(!check.available)return toast(`${line.name} cannot be ordered. Please ask the Owner to restock: ${check.shortages.map(x=>x.name).join(', ')}.`)}let total=cart.reduce((a,c)=>a+c.price*c.qty,0),cash=Number($('#cash').value);if(cash<total)return toast('Cash received must cover the order total.');let id=String(Math.max(0,...db.orders.map(o=>Number(o.id)))+1).padStart(3,'0'),items=cart.map(c=>`${c.name} × ${c.qty}`).join(', ');let order={id,date:localDateKey(),customer:$('#customer').value||'Walk-in',notes:$('#custom').value||'',items,lines:cart.map(c=>({...c,recipe:c.recipe||recipeForProduct(c)})),total,cashReceived:cash,status:'Pending',time:new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})};db.orders.unshift(order);applyOrderStock(order,1);save();cart=[];persistCart();sessionStorage.removeItem('bbPosDraft');let change=cash-total;modal('Order confirmed',`<div class="notice success">Order number <b>#${id}</b> has been recorded.</div><p>${items}</p><p>Total: <b>${money(total)}</b></p><p>Cash received: ${money(cash)}</p><p>Change: <b>${money(change)}</b></p>`,'New order',()=>{location.reload()})}
function updateOrder(id){let o=db.orders.find(x=>x.id===id);modal('Update order status',`<div class="field"><label>Order #${id}</label><select id="new-status"><option ${o.status==='Pending'?'selected':''}>Pending</option><option ${o.status==='Preparing'?'selected':''}>Preparing</option><option ${o.status==='Completed'?'selected':''}>Completed</option></select></div>`,'Update',()=>{o.status=$('#new-status').value;save();location.reload()})}
function cancelOrder(id){let o=db.orders.find(x=>x.id===id);modal(`Cancel order #${id}`,`<p>Only orders not yet prepared or served may be cancelled. Stock will be restored in the live system.</p><div class="field"><label>Reason for cancellation</label><textarea id="cancel-reason" placeholder="Enter reason" required></textarea></div>`,'Confirm cancellation',()=>{if(!$('#cancel-reason').value.trim())return toast('A reason is required.');if(o.stockDeducted)applyOrderStock(o,-1);o.status='Cancelled';o.reason=$('#cancel-reason').value;save();location.reload()})}
function refundRequest(id){let o=db.orders.find(x=>x.id===id);modal(`Request refund · Order #${id}`,`<div class="notice">Refunds are only for orders not yet served and require Owner/Manager approval.</div><p>Amount: <b>${money(o.total)}</b></p><div class="field"><label>Reason</label><textarea id="refund-reason" placeholder="Enter refund reason"></textarea></div>`,'Submit request',()=>{db.requests.unshift({id:'RF-'+String(db.requests.length+1).padStart(3,'0'),date:new Date().toLocaleString(),dayKey:localDateKey(),order:id,requestedBy:'Barista',amount:o.total,reason:$('#refund-reason').value,status:'For approval'});save();toast('Refund request sent to Owner/Manager.')})}
function inventoryPage(){return pageHead('Inventory','Ingredient stock, FIFO monitoring and stock movement records',`<button class="btn primary" onclick="stockModal()">＋ Update stock</button>`)+stats([['Ingredient items',db.stock.length,''],['Available',db.stock.filter(s=>s.qty>s.min).length,''],['Low stock',db.stock.filter(s=>s.qty<=s.min&&s.qty>0).length,''],['Out of stock',db.stock.filter(s=>s.qty===0).length,'']])+`<section class="panel"><h2>Ingredient inventory</h2>${table(['Ingredient','Current stock','Unit','Alert threshold','Status','Action'],db.stock.map((s,i)=>`<tr><td>${s.name}</td><td>${s.qty.toLocaleString()}</td><td>${s.unit}</td><td>${s.min}</td><td>${status(s.qty===0?'Out-of-Stock':s.qty<=s.min?'Low-Stock':'Available')}</td><td><button class="btn small" onclick="stockModal(${i})">Edit</button> <button class="btn small danger" onclick="deleteStock(${i})">Delete</button></td></tr>`).join(''))}</section><section class="panel"><h2>Inventory notes</h2><p class="muted">Stock levels are automatically deducted per order in the connected system. Baristas can scan barcodes and view stock status only; stock-in, adjustment and disposal are Owner/Manager actions.</p></section>`}
function deleteStock(i){let item=db.stock[i];if(!item)return;modal('Delete inventory item',`<p>Are you sure you want to delete <b>${escapeHTML(item.name)}</b> from ingredient inventory?</p><div class="notice warn">This removes the ingredient from stock monitoring and future inventory counts. Existing orders and reports will remain unchanged.</div>`,'Delete ingredient',()=>{db.stock.splice(i,1);save();location.reload()})}
function stockModal(i){let s=i===undefined?{name:'',qty:0,min:0,unit:'pcs'}:db.stock[i];modal(i===undefined?'Add ingredient':'Update stock',`<div class="field"><label>Ingredient name</label><input id="s-name" value="${s.name}"></div><div class="form-row"><div class="field"><label>Quantity</label><input id="s-qty" type="number" value="${s.qty}"></div><div class="field"><label>Unit</label><input id="s-unit" value="${s.unit}"></div></div><div class="field"><label>Low-stock threshold</label><input id="s-min" type="number" value="${s.min}"></div><div class="field"><label>Movement type</label><select id="s-type"><option>Stock-In</option><option>Adjustment</option><option>Disposal</option></select></div>`,'Save stock',()=>{let obj={name:$('#s-name').value,qty:Number($('#s-qty').value),unit:$('#s-unit').value,min:Number($('#s-min').value)};if(i===undefined)db.stock.push(obj);else db.stock[i]=obj;save();location.reload()})}
function stockReadOnly(){return pageHead('Stock status','Read-only ingredient availability for POS users')+`<div class="notice">Inventory access is read-only for Barista accounts. Please inform the Owner/Manager if an item needs restocking.</div><section class="panel"><h2>Current stock · Read only</h2>${table(['Ingredient','Current stock','Unit','Status'],db.stock.map(s=>`<tr><td>${s.name}</td><td>${s.qty}</td><td>${s.unit}</td><td>${status(s.qty===0?'Out-of-Stock':s.qty<=s.min?'Low-Stock':'Available')}</td></tr>`).join(''))}</section>`}
function costingPage(){return pageHead('Menu, recipes & product costing','Manage drinks, recipe ingredients, packaging cost and selling price',`<button class="btn primary" onclick="productModal()">＋ Add drink</button>`)+`<div class="notice">The starter menu follows the Project Charter's Company Products list: Coffee, Non-Coffee and Refreshers. Example prices and costs are placeholders, not confirmed shop prices. Update them using the approved menu and costing information.</div><section class="panel"><h2>Drinks menu (${db.products.length})</h2>${table(['Product','Category','Selling price','Estimated cost','Gross margin','Action'],db.products.map((p,i)=>`<tr><td>${escapeHTML(p.name)}</td><td>${escapeHTML(p.category)}</td><td>${money(p.price)}</td><td>${money(p.cost||0)}</td><td>${money(p.price-(p.cost||0))}</td><td><button class="btn small" onclick="productModal(${i})">Edit</button> <button class="btn small danger" onclick="deleteProduct(${i})">Delete</button></td></tr>`).join(''))}</section><div class="notice">The project scope covers drinks only: coffee, non-coffee and refreshers. Food items are excluded. Deleting a menu item removes it from future POS orders; past transaction records remain unchanged.</div>`}
function deleteProduct(i){const p=db.products[i];if(!p)return;modal('Delete menu item',`<p>Are you sure you want to delete <b>${escapeHTML(p.name)}</b> from the menu?</p><div class="notice">This removes the drink from future POS orders. Existing completed or recorded orders will keep their original item details.</div>`,'Delete drink',()=>{db.products.splice(i,1);save();location.reload()})}
function productModal(i){let p=i===undefined?{name:'',price:0,category:'Coffee',cost:0,image:''}:db.products[i];modal(i===undefined?'Add drink':'Edit drink',`<div class="field"><label>Product name</label><input id="p-name" value="${escapeHTML(p.name)}"></div><div class="form-row"><div class="field"><label>Category</label><select id="p-cat"><option ${p.category==='Coffee'?'selected':''}>Coffee</option><option ${p.category==='Non-Coffee'?'selected':''}>Non-Coffee</option><option ${p.category==='Refreshers'?'selected':''}>Refreshers</option></select></div><div class="field"><label>Selling price</label><input id="p-price" type="number" value="${p.price}"></div></div><div class="field"><label>Estimated product cost</label><input id="p-cost" type="number" value="${p.cost||45}"></div><div class="field"><label>Menu photo</label><input id="p-image" type="file" accept="image/*"><small class="muted">Upload a JPG or PNG photo to display on the POS menu.</small>${p.image?`<img class="product-photo preview-photo" src="${p.image}" alt="Current product photo">`:''}</div>`,'Save product',()=>{let file=$('#p-image').files[0],saveProduct=image=>{let obj={...p,name:$('#p-name').value.trim(),category:$('#p-cat').value,price:Number($('#p-price').value),cost:Number($('#p-cost').value),image};if(!obj.name)return toast('Enter a product name.');if(i===undefined)db.products.push(obj);else db.products[i]=obj;save();location.reload()};if(file){if(file.size>1500000){toast('Please choose an image under 1.5 MB.');return false}let reader=new FileReader();reader.onload=()=>saveProduct(reader.result);reader.readAsDataURL(file);return false}saveProduct(p.image||'')})}
function salesAnalytics(){let mode=new URLSearchParams(location.search).get('period')||'day',now=new Date(),labels=[],keys=[];if(mode==='day'){for(let i=6;i>=0;i--){let d=new Date(now);d.setDate(now.getDate()-i);keys.push(d.toISOString().slice(0,10));labels.push(d.toLocaleDateString('en',{month:'short',day:'numeric'}))}}else if(mode==='week'){for(let i=7;i>=0;i--){let d=new Date(now);d.setDate(now.getDate()-i*7);let start=new Date(d);start.setDate(d.getDate()-((d.getDay()+6)%7));keys.push(start.toISOString().slice(0,10));labels.push('Wk '+start.toLocaleDateString('en',{month:'short',day:'numeric'}))}}else{for(let i=11;i>=0;i--){let d=new Date(now.getFullYear(),now.getMonth()-i,1);keys.push(`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`);labels.push(d.toLocaleDateString('en',{month:'short'}))}}let vals=keys.map(k=>db.orders.filter(o=>o.status==='Completed'&&(mode==='month'?String(o.date||'').slice(0,7)===k:mode==='week'?(()=>{let od=new Date((o.date||'')+'T00:00:00'),st=new Date(k+'T00:00:00'),en=new Date(st);en.setDate(st.getDate()+7);return od>=st&&od<en})():o.date===k)).reduce((a,o)=>a+Number(o.total||0),0));let max=Math.max(1,...vals),pts=vals.map((v,i)=>`${40+i*(640/Math.max(1,vals.length-1))},${180-(v/max)*145}`).join(' ');let pie={};db.orders.filter(o=>o.status==='Completed').forEach(o=>(o.lines||[]).forEach(l=>pie[l.name]=(pie[l.name]||0)+Number(l.price||0)*Number(l.qty||0)));let entries=Object.entries(pie).sort((a,b)=>b[1]-a[1]).slice(0,6),sum=entries.reduce((a,x)=>a+x[1],0),colors=['#76513b','#c28b42','#43836b','#8b6aa8','#d27b65','#6d9ca0'];let angle=0,stops=entries.map(([n,v],i)=>{let a=angle;angle+=sum?v/sum*100:0;return `${colors[i]} ${a}% ${angle}%`}).join(', ');return `<section class="panel"><div class="inline" style="justify-content:space-between;flex-wrap:wrap"><div><h2>Sales performance</h2><p class="muted">Based on completed transactions only</p></div><div class="tabs"><a class="tab ${mode==='day'?'active':''}" href="reports.html?period=day">Daily</a><a class="tab ${mode==='week'?'active':''}" href="reports.html?period=week">Weekly</a><a class="tab ${mode==='month'?'active':''}" href="reports.html?period=month">Monthly</a></div></div><div class="sales-chart"><svg viewBox="0 0 720 220" role="img" aria-label="Sales line graph"><line x1="40" y1="180" x2="680" y2="180" stroke="#dfd3c6"/><line x1="40" y1="35" x2="40" y2="180" stroke="#dfd3c6"/><polyline points="${pts}" fill="none" stroke="#76513b" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>${vals.map((v,i)=>{let x=40+i*(640/Math.max(1,vals.length-1)),y=180-(v/max)*145;return `<circle cx="${x}" cy="${y}" r="5" fill="#c28b42"><title>${labels[i]}: ${money(v)}</title></circle><text x="${x}" y="204" text-anchor="middle" font-size="10" fill="#8c7b6b">${labels[i]}</text>`}).join('')}</svg></div><div class="chart-legend"><span>● Sales</span><b>${money(vals.reduce((a,v)=>a+v,0))} in selected view</b></div></section><div class="grid two"><section class="panel"><h2>Sales breakdown by drink</h2>${entries.length?`<div class="pie-wrap"><div class="pie-chart" style="background:conic-gradient(${stops})"></div><div class="pie-legend">${entries.map(([n,v],i)=>`<div><i style="background:${colors[i]}"></i><span>${escapeHTML(n)}</span><b>${money(v)}</b></div>`).join('')}</div></div>`:'<div class="empty">No completed sales to display yet.</div>'}</section><section class="panel"><h2>${mode==='day'?'Daily':mode==='week'?'Weekly':'Monthly'} sales totals</h2>${table(['Period','Sales'],labels.map((l,i)=>`<tr><td>${l}</td><td>${money(vals[i])}</td></tr>`).join(''))}</section></div>`}
function expenseOrderHistory(){const params=new URLSearchParams(location.search),selectedDate=params.get('ordersDate')||localDateKey(),orders=db.orders.filter(o=>recordDayKey(o)===selectedDate).sort((a,b)=>String(b.time||'').localeCompare(String(a.time||''))),completed=orders.filter(o=>o.status==='Completed'),total=completed.reduce((sum,o)=>sum+Number(o.total||0),0),rows=orders.map(o=>`<tr><td>#${escapeHTML(o.id)}</td><td>${escapeHTML(o.time||'')}</td><td>${escapeHTML(o.customer||'Walk-in')}</td><td>${escapeHTML(o.items||'')}</td><td>${money(o.total)}</td><td>${status(o.status)}</td></tr>`).join('');return `<section class="panel"><div class="inline" style="justify-content:space-between;flex-wrap:wrap"><div><h2>Order history</h2><p class="muted">Browse all recorded orders by selecting a date. Historical transactions are retained.</p></div><div class="field" style="min-width:220px"><label for="expense-orders-date">Choose order date</label><input type="date" id="expense-orders-date" value="${escapeHTML(selectedDate)}" onchange="filterExpenseOrderHistory(this.value)"></div></div><div class="inline" style="justify-content:flex-end"><button class="btn small" onclick="filterExpenseOrderHistory(localDateKey())">Today</button></div>${stats([['Orders on selected date',orders.length,selectedDate],['Completed orders',completed.length,'Selected date'],['Completed sales',money(total),'Selected date']])}${table(['Order #','Time','Customer','Items','Total','Status'],rows)}</section>`}
function filterExpenseOrderHistory(date){if(!date)return;location.href='reports.html?ordersDate='+encodeURIComponent(date)}
function reportsPage(){let completed=db.orders.filter(o=>o.status==='Completed'),todayCompleted=todaysOrders().filter(o=>o.status==='Completed'),sales=todayCompleted.reduce((a,o)=>a+o.total,0),expenses=todaysExpenses().reduce((a,e)=>a+e.amount,0),productCosts=todayCompleted.reduce((sum,o)=>sum+(o.lines||[]).reduce((n,line)=>n+(Number(line.cost)||0)*line.qty,0),0),units={};completed.forEach(o=>(o.lines||[]).forEach(line=>units[line.name]=(units[line.name]||0)+line.qty));let bestRows=Object.entries(units).sort((a,b)=>b[1]-a[1]).map(([name,count])=>{let p=db.products.find(x=>x.name===name);return `<tr><td>${escapeHTML(name)}</td><td>${count}</td><td>${money((p?.price||0)*count)}</td></tr>`}).join('');return pageHead('Reports & expenses','Daily activity rolls over automatically; historical sales and expenses remain saved',`<button class="btn" onclick="exportCSV()">Export CSV</button><button class="btn primary" onclick="expenseModal()">＋ Add expense</button>`)+stats([["Today's sales",money(sales),'Completed transactions'],['Expenses',money(expenses),"Today's recorded expenses"],["Today's product costs",money(productCosts),'From completed order recipes'],["Today's net profit / loss",money(sales-expenses-productCosts),'Sales less costs and expenses']])+salesAnalytics()+expenseOrderHistory()+`<section class="panel"><h2>Expense summary</h2>${table(['Expense','Category','Date','Amount'],db.expenses.map(e=>`<tr><td>${escapeHTML(e.name)}</td><td>${escapeHTML(e.category)}</td><td>${escapeHTML(e.date)}</td><td>${money(e.amount)}</td></tr>`).join(''))}</section><section class="panel"><h2>Best-selling products</h2>${table(['Product','Units sold','Sales'],bestRows)}</section>`}
function exportCSV(){let rows=[['Order','Customer','Items','Total','Status'],...db.orders.map(o=>[o.id,o.customer,o.items,o.total,o.status])];let csv=rows.map(r=>r.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='brews-blessings-sales.csv';a.click();URL.revokeObjectURL(a.href)}
function approvalsPage(){let tab=new URLSearchParams(location.search).get('tab')||'refunds';let refunds=todaysRecords(db.requests||[]),voids=todaysRecords(db.voids||[]),verified=todaysRecords(db.salesVerifications||[]);return pageHead('Approvals & verification','Daily queues restart each day. Previous requests, voids and verification records remain saved.')+`<div class="tabs"><a class="tab ${tab==='refunds'?'active':''}" href="approvals.html?tab=refunds">Refund requests</a><a class="tab ${tab==='voids'?'active':''}" href="approvals.html?tab=voids">Voids</a><a class="tab ${tab==='sales'?'active':''}" href="approvals.html?tab=sales">Daily sales</a><a class="tab ${tab==='shifts'?'active':''}" href="approvals.html?tab=shifts">Shift approvals</a></div>${tab==='refunds'?`<section class="panel"><h2>Today's refund requests</h2><p class="muted">Only today's requests appear here. Older requests remain in saved records.</p>${table(['Request','Order','Requested by','Amount','Reason','Status','Action'],refunds.map(r=>{let i=db.requests.indexOf(r);return `<tr><td>${escapeHTML(r.id)}</td><td>#${escapeHTML(r.order)}</td><td>${escapeHTML(r.requestedBy)}</td><td>${money(r.amount)}</td><td>${escapeHTML(r.reason)}</td><td>${status(r.status)}</td><td>${r.status==='For approval'?`<button class="btn small" onclick="approveRefund(${i},true)">Approve</button> <button class="btn small danger" onclick="approveRefund(${i},false)">Reject</button>`:'—'}</td></tr>`}).join(''))}</section>`:tab==='voids'?`<section class="panel"><div class="inline" style="justify-content:space-between"><h2>Today's voided transactions</h2><button class="btn primary" onclick="voidModal()">＋ Void transaction</button></div><p class="muted">Only today's voids appear here. Older void records are retained.</p>${table(['Date','Order','Voided by','Amount','Reason'],voids.map(v=>`<tr><td>${escapeHTML(v.date)}</td><td>#${escapeHTML(v.order)}</td><td>${escapeHTML(v.by)}</td><td>${money(v.amount)}</td><td>${escapeHTML(v.reason)}</td></tr>`).join(''))}</section>`:tab==='sales'?`<section class="panel"><h2>Daily sales verification</h2><p class="muted">Today's verification starts fresh each day. Previous verification records remain saved below only when they belong to today; historical orders remain in Order history.</p>${table(['Order','Customer','Items','Total','Status','Time'],todaysOrders().map(o=>`<tr><td>#${escapeHTML(o.id)}</td><td>${escapeHTML(o.customer)}</td><td>${escapeHTML(o.items)}</td><td>${money(o.total)}</td><td>${status(o.status)}</td><td>${escapeHTML(o.time||'')}</td></tr>`).join(''))}<div class="total"><span>Today's completed sales total</span><b>${money(todaysOrders().filter(o=>o.status==='Completed').reduce((a,o)=>a+o.total,0))}</b></div><button class="btn primary" onclick="verifySales()">Verify today's sales</button><h3>Today's verification records</h3>${table(['Verified at','Verified by','Sales total','Note'],verified.map(v=>`<tr><td>${escapeHTML(v.date)}</td><td>${escapeHTML(v.by)}</td><td>${money(v.total)}</td><td>${escapeHTML(v.note)}</td></tr>`).join(''))}</section>`:`<section class="panel"><h2>Today's shift check submissions</h2><p class="muted">Review today's barista submissions. Older shift records remain available in Shift overview.</p>${table(['Date','Shift','Submitted by','Cash counted','Status','Notes','Action'],todaysShifts().map(c=>{let i=db.shiftChecks.indexOf(c);return `<tr><td>${escapeHTML(c.date)}</td><td>${escapeHTML(c.type)}</td><td>${escapeHTML(c.name)}</td><td>${money(c.cashActual)}</td><td>${status(c.status)}</td><td>${escapeHTML(c.notes||'')}</td><td>${c.status==='For approval'?`<button class="btn small" onclick="reviewShift(${i},true)">Approve</button> <button class="btn small danger" onclick="reviewShift(${i},false)">Reject</button>`:'—'}</td></tr>`}).join(''))}</section>`}`}
function approveRefund(i,ok){db.requests[i].status=ok?'Approved':'Rejected';let order=db.orders.find(o=>o.id===db.requests[i].order);if(ok&&order){if(order.stockDeducted)applyOrderStock(order,-1);order.status='Refunded'}save();location.href='approvals.html?tab=refunds'}
function verifySales(){let total=db.orders.filter(o=>o.date===localDateKey()&&o.status==='Completed').reduce((a,o)=>a+o.total,0);modal('Verify daily sales',`<p>Completed orders: <b>${db.orders.filter(o=>o.date===localDateKey()&&o.status==='Completed').length}</b></p><p>Completed sales total: <b>${money(total)}</b></p><div class="field"><label>Verification note</label><textarea id="verify-note" placeholder="Optional note"></textarea></div>`,'Confirm verification',()=>{db.salesVerifications=db.salesVerifications||[];db.salesVerifications.unshift({date:new Date().toLocaleString(),dayKey:localDateKey(),by:currentUser()?.name||'Owner',total,note:$('#verify-note').value});save();toast('Daily sales verified and recorded.');location.href='approvals.html?tab=sales'})}
function voidModal(){modal('Void a transaction',`<div class="field"><label>Order number</label><input id="void-id" placeholder="Enter order number"></div><div class="field"><label>Reason for voiding</label><textarea id="void-reason" placeholder="Required reason"></textarea></div>`,'Void transaction',()=>{let id=$('#void-id').value.trim().replace(/^#/,'');let order=db.orders.find(o=>String(o.id)===id);if(!order)return toast('Order number was not found.');let reason=$('#void-reason').value.trim();if(!reason)return toast('A reason is required.');db.voids=db.voids||[];db.voids.unshift({date:new Date().toLocaleString(),dayKey:localDateKey(),order:id,by:currentUser()?.name||'Owner',amount:order.total,reason});if(order.stockDeducted)applyOrderStock(order,-1);order.status='Voided';save();toast('Transaction voided and recorded.');location.href='approvals.html?tab=voids'})}
function reviewShift(i,approved){let c=db.shiftChecks[i];if(!c||c.status!=='For approval')return toast('This shift check has already been reviewed.');c.status=approved?'Approved':'Rejected';c.reviewedBy=currentUser()?.name||'Owner';c.reviewedAt=new Date().toLocaleString();save();toast(`Shift check ${approved?'approved':'rejected'}.`);location.href='approvals.html?tab=shifts'}
function shiftPage(role){let checks=db.shiftChecks||[],todayChecks=todaysShifts();return pageHead(role==='owner'?'Shift overview':'My shift check',role==='owner'?'Review your own shift records and see submissions awaiting approval.':'Submit your opening or closing cash and inventory count for Owner/Manager review.')+(role==='owner'?`<section class="panel"><div class="inline" style="justify-content:space-between"><h2>Pending barista submissions</h2><a class="btn small" href="approvals.html?tab=shifts">Open approvals</a></div>${table(['Date','Shift','Submitted by','Cash counted','Status'],checks.filter(c=>c.status==='For approval').map(c=>`<tr><td>${escapeHTML(c.date)}</td><td>${escapeHTML(c.type)}</td><td>${escapeHTML(c.name)}</td><td>${money(c.cashActual)}</td><td>${status(c.status)}</td></tr>`).join(''))}</section>`:`<section class="panel"><h2>Submit a shift check</h2><p class="muted">Choose whether this is your opening or closing count. After submission, the Owner/Manager reviews it under Approvals & verification → Shift approvals.</p><div class="field"><label>Shift check type</label><select id="shift-type"><option>Opening</option><option>Closing</option></select></div><div class="notice"><b>Automatic cash calculation:</b> The amount below is calculated from recorded cash sales (excluding cancelled, voided, and refunded orders). No manual cash entry is needed.</div><div class="field"><label>System-calculated cash in drawer (₱)</label><input id="cash-count" type="text" value="${money(expectedCashInDrawer())}" readonly></div><h3>System inventory count</h3><p class="muted">Ingredient quantities update automatically when an order is placed. These are system-generated stock levels, not a physical verification count.</p>${db.stock.map((item,i)=>`<div class="cartline"><span>${escapeHTML(item.name)}</span><b>${Number(item.qty).toLocaleString()} ${escapeHTML(item.unit)}</b></div>`).join('')||'<p class="muted">No inventory items have been added yet.</p>'}<div class="field"><label>Notes / explanation for differences</label><textarea id="shift-note" placeholder="Optional explanation"></textarea></div><button class="btn primary" onclick="submitShift()">Submit for Owner approval</button></section>`)+`<section class="panel"><h2>${role==='owner'?'Shift history':'My submitted shift checks'}</h2>${table(['Date','Type','Submitted by','Cash counted','Status','Notes'],checks.filter(c=>role==='owner'||c.userId===currentUser()?.id).map(c=>`<tr><td>${escapeHTML(c.date)}</td><td>${escapeHTML(c.type)}</td><td>${escapeHTML(c.name)}</td><td>${money(c.cashActual)}</td><td>${status(c.status)}</td><td>${escapeHTML(c.notes||'')}</td></tr>`).join(''))}</section>`}
function submitShift(){let cash=expectedCashInDrawer();let type=$('#shift-type').value,stockCounts=db.stock.map(item=>({name:item.name,system:Number(item.qty||0),actual:Number(item.qty||0),unit:item.unit,autoGenerated:true}));db.shiftChecks=db.shiftChecks||[];db.shiftChecks.unshift({date:new Date().toLocaleString(),dayKey:localDateKey(),type,name:currentUser()?.name||'',userId:currentUser()?.id,cashActual:cash,stockCounts,notes:$('#shift-note').value,status:'For approval',autoGenerated:true});save();toast('Shift check submitted with automatically calculated cash and system inventory counts.');location.href='shift.html'}
function renderAccountsTable(){
 let users=getUsers(),me=currentUser();
 return `<div class="inline" style="justify-content:space-between;margin:12px 0 8px"><b>Saved accounts</b><span class="pill account-count">${users.length} account${users.length===1?'':'s'}</span></div><div class="table-wrap"><table><thead><tr><th>Display name</th><th>Username</th><th>Role</th><th>Action</th></tr></thead><tbody id="accounts-tbody">${users.map(u=>`<tr><td>${escapeHTML(u.name)}</td><td>${escapeHTML(u.username)}</td><td>${u.role==='owner'?'Owner / Manager':'Barista'}</td><td>${u.username===me?.username?'<span class="muted">Current account</span>':`<button class="btn danger small" onclick="deleteUserAccount('${String(u.id).replace(/'/g,'')}')">Delete</button>`}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No accounts found</td></tr>'}</tbody></table></div>`;
}
function refreshAccountsTable(){
 let wrap=$('#accounts-list');
 if(wrap)wrap.innerHTML=renderAccountsTable();
}
function deleteUserAccount(id){
 let users=getUsers(),target=users.find(u=>String(u.id)===String(id));
 if(!target)return toast('Account not found.');
 let me=currentUser();
 if(target.username===me?.username)return toast('You cannot delete the account currently signed in.');
 if(target.username===INITIAL_OWNER.username)return toast('The primary Owner account cannot be deleted.');
 if(target.role==='owner'&&users.filter(u=>u.role==='owner').length<=1)return toast('At least one Owner account must remain.');
 modal('Delete account?',`<div class="notice warn">You are about to delete this account. The user will no longer be able to sign in.</div><p><b>${escapeHTML(target.name)}</b></p><p>${escapeHTML(target.username)} · ${target.role==='owner'?'Owner / Manager':'Barista'}</p><p>This action cannot be undone.</p>`,'Delete account',()=>{let latest=getUsers();saveUsers(latest.filter(u=>String(u.id)!==String(id)));refreshAccountsTable();toast('Account deleted successfully.');return true});
}

function settingsPage(){return pageHead('Settings & backup','Manage user access, session security and backup storage')+`<div class="grid two"><section class="panel"><h2>User accounts & roles</h2><p class="muted">Only Owner / Manager accounts can add or delete staff accounts. The primary Owner and currently signed-in account are protected.</p><button class="btn primary" onclick="userModal()">＋ Add user account</button><div id="accounts-list">${renderAccountsTable()}</div></section><section class="panel"><h2>Session security</h2><div class="field"><label>Automatic logout after inactivity</label><select><option>15 minutes</option><option>30 minutes</option><option>60 minutes</option></select></div><button class="btn" onclick="toast('Security settings saved in this demo.')">Save security settings</button></section></div><div class="grid two"><section class="panel"><h2>Backup data</h2><p class="muted">Create a backup copy of sales, inventory and business records.</p><button class="btn primary" onclick="backupData()">Create backup</button><div class="notice">Backup storage: external drive / cloud plan (configured by administrator).</div></section><section class="panel"><h2>Restore backup</h2><p class="muted">Restore saved data. This action should be performed only by an authorized Owner/Manager.</p><input type="file" id="restore-file" accept=".json"><div class="spacer"></div><button class="btn" onclick="restoreData()">Restore selected backup</button></section></div>`}
function userModal(){modal('Create staff account',`<div class="field"><label>Full name / Display name</label><input id="u-display" placeholder="Enter staff member's name" required></div><div class="field"><label>Username</label><input id="u-name" autocomplete="off" placeholder="Create username" required></div><div class="field"><label>Role</label><select id="u-role"><option value="barista">POS User / Employee (Barista)</option><option value="owner">Owner / Manager</option></select></div><div class="field"><label>Password</label><div class="password-wrap"><input id="u-pass" type="password" autocomplete="new-password" placeholder="Create password" required><button type="button" class="eye-btn" onclick="togglePassword('u-pass',this)" aria-label="Show password">◉</button></div></div><div class="field"><label>Confirm password</label><div class="password-wrap"><input id="u-confirm" type="password" autocomplete="new-password" placeholder="Re-enter password" required><button type="button" class="eye-btn" onclick="togglePassword('u-confirm',this)" aria-label="Show password">◉</button></div></div>`,'Create account',()=>{let name=$('#u-display').value.trim(),username=$('#u-name').value.trim(),password=$('#u-pass').value,confirm=$('#u-confirm').value,role=$('#u-role').value;if(!name||!username||!password){toast('Please complete all account fields.');return false}if(password!==confirm){toast('Passwords do not match.');return false}let users=getUsers();if(users.some(u=>u.username.toLowerCase()===username.toLowerCase())){toast('That username is already taken.');return false}users.push({id:Date.now(),name,username,password,role});saveUsers(users);refreshAccountsTable();toast('Account created successfully. It is ready to use immediately.');return true})}

function backupData(){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));a.download='brews-blessings-backup.json';a.click();URL.revokeObjectURL(a.href);toast('Backup file generated.')}
function restoreData(){let f=$('#restore-file').files[0];if(!f)return toast('Choose a backup JSON file first.');let r=new FileReader();r.onload=()=>{try{db=JSON.parse(r.result);save();toast('Backup restored. Reloading…');setTimeout(()=>location.reload(),700)}catch(e){toast('Invalid backup file.')}};r.readAsText(f)}
function init(){seedStarterMenu();let path=location.pathname.split('/').pop().replace('.html',''),role=location.pathname.includes('/barista/')?'barista':'owner',user=currentUser();if(!user){location.href='../index.html';return}if(user.role!==role|| (path==='history'&&role!=='owner')){location.href=user.role==='owner'?'../owner/dashboard.html':'../barista/dashboard.html';return}let content='';if(path==='dashboard')content=role==='owner'?ownerDashboard():baristaDashboard();if(path==='pos')content=posPage(role);if(path==='history'&&role==='owner')content=orderHistoryPage();if(path==='inventory')content=inventoryPage();if(path==='stock')content=stockReadOnly();if(path==='costing')content=costingPage();if(path==='reports')content=reportsPage();if(path==='approvals')content=approvalsPage();if(path==='shift')content=shiftPage(role);if(path==='settings')content=settingsPage();shell(role,path,content);if(path==='pos')restorePosDraft()}
function togglePassword(id,btn){let input=document.getElementById(id);if(!input)return;input.type=input.type==='password'?'text':'password';btn.textContent=input.type==='password'?'◉':'◎';btn.setAttribute('aria-label',input.type==='password'?'Show password':'Hide password')}
function loginUser(e){e.preventDefault();let username=$('#login-username').value.trim(),password=$('#login-password').value,users=getUsers(),user=users.find(u=>u.username.toLowerCase()===username.toLowerCase()&&u.password===password);if(!user){$('#login-error').textContent='Incorrect username or password. Please try again.';$('#login-error').hidden=false;return}setCurrentUser({id:user.id,name:user.name,username:user.username,role:user.role});location.href=user.role==='owner'?'owner/dashboard.html':'barista/dashboard.html'}
window.addEventListener('DOMContentLoaded',()=>{if($('#login-form')){ensureInitialOwner();$('#login-form').addEventListener('submit',loginUser)}else init()});
